description:
Write the pieces of lesson 3.03:

```cpp
float gravityFor(float height, float riseTime);     // 2h / t²
float jumpSpeedFor(float height, float riseTime);   // 2h / t
float approach(float v, float target, float maxDelta);

struct Jumper { float coyote{ 0 }, buffer{ 0 }; };
bool wantsJump(Jumper& j, bool onGround, bool pressed, float dt, float window);
float cutJump(float velY, bool released);
```

- `approach` moves `v` towards `target` by at most `maxDelta` (which is never negative) and never past it.
- `wantsJump`, called once per frame, in this order:
  1. `coyote` becomes `window` when on the ground, otherwise it goes down by `dt`;
  2. `buffer` becomes `window` when jump was pressed this frame, otherwise it goes down by `dt`;
  3. if both are above zero, both are set to zero and the function returns `true` (jump now).
- `cutJump` halves the vertical speed when the button was released while still rising (`velY < 0`); otherwise returns it unchanged.

starter.solution.cpp:
struct Jumper { float coyote{ 0 }, buffer{ 0 }; };

float gravityFor(float height, float riseTime) { return 0; }
float jumpSpeedFor(float height, float riseTime) { return 0; }
float approach(float v, float target, float maxDelta) { return v; }
bool wantsJump(Jumper& j, bool onGround, bool pressed, float dt, float window) { return false; }
float cutJump(float velY, bool released) { return velY; }

solution.solution.cpp:
#include <algorithm>

struct Jumper { float coyote{ 0 }, buffer{ 0 }; };

float gravityFor(float height, float riseTime) { return 2.0f * height / (riseTime * riseTime); }
float jumpSpeedFor(float height, float riseTime) { return 2.0f * height / riseTime; }

float approach(float v, float target, float maxDelta)
{
    if (v < target) return std::min(v + maxDelta, target);
    return std::max(v - maxDelta, target);
}

bool wantsJump(Jumper& j, bool onGround, bool pressed, float dt, float window)
{
    j.coyote = onGround ? window : j.coyote - dt;
    j.buffer = pressed ? window : j.buffer - dt;
    if (j.coyote > 0 && j.buffer > 0)
    {
        j.coyote = 0;
        j.buffer = 0;
        return true;
    }
    return false;
}

float cutJump(float velY, bool released)
{
    return released && velY < 0 ? velY * 0.5f : velY;
}

unitTests:
TEST("designed jump") { CHECK_NEAR(gravityFor(96, 0.4f), 1200.0, 1e-2); CHECK_NEAR(jumpSpeedFor(96, 0.4f), 480.0, 1e-3); CHECK_NEAR(gravityFor(64, 0.5f), 512.0, 1e-2); }
TEST("approach") { CHECK_NEAR(approach(0, 200, 50), 50.0, 1e-6); CHECK_NEAR(approach(190, 200, 50), 200.0, 1e-6); CHECK_NEAR(approach(100, -100, 30), 70.0, 1e-6); CHECK_NEAR(approach(-80, -100, 30), -100.0, 1e-6); }
TEST("jump from the ground") { Jumper j; CHECK(wantsJump(j, true, true, 0.016f, 0.1f)); CHECK(!wantsJump(j, true, false, 0.016f, 0.1f)); }
TEST("coyote time") {
    Jumper j; wantsJump(j, true, false, 0.02f, 0.1f);
    CHECK(!wantsJump(j, false, false, 0.02f, 0.1f)); CHECK(wantsJump(j, false, true, 0.02f, 0.1f));
    Jumper k; wantsJump(k, true, false, 0.02f, 0.1f); for (int i = 0; i < 5; ++i) wantsJump(k, false, false, 0.02f, 0.1f);
    CHECK(!wantsJump(k, false, true, 0.02f, 0.1f));
}
TEST("buffered press") {
    Jumper j; CHECK(!wantsJump(j, false, true, 0.02f, 0.1f)); CHECK(!wantsJump(j, false, false, 0.02f, 0.1f));
    CHECK(wantsJump(j, true, false, 0.02f, 0.1f)); CHECK(!wantsJump(j, true, false, 0.02f, 0.1f));
    Jumper k; wantsJump(k, false, true, 0.05f, 0.1f); wantsJump(k, false, false, 0.05f, 0.1f); CHECK(!wantsJump(k, true, false, 0.05f, 0.1f));
}
TEST("cutting the jump") { CHECK_NEAR(cutJump(-400, true), -200.0, 1e-6); CHECK_NEAR(cutJump(-400, false), -400.0, 1e-6); CHECK_NEAR(cutJump(100, true), 100.0, 1e-6); }

